package com.today.app.ui.components

import android.content.Context
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.core.graphics.toColorInt
import org.json.JSONArray
import org.json.JSONObject

/**
 * The illustrated character's art, generated by the authoring tool into assets/character_art.json:
 * part key ("eyes.F.almond.happy.R") -> layers, drawn in a 200 x 560 box whose top is y = -45
 * (room above the head for hats, below the soles for the leg-length slider).
 * Layers can carry morph targets: how their points move per unit of each fine-tune slider
 * ([params], e.g. "jaw", "shoulders").
 */
object CharacterArt {
    const val W = 200f
    const val H = 560f
    const val TOP = -45f

    @Volatile
    private var art: Art? = null

    internal fun art(context: Context): Art = art ?: synchronized(this) { art ?: load(context).also { art = it } }

    internal fun parts(context: Context): Map<String, List<ArtLayer>> = art(context).parts

    /** Parses everything once, e.g. from a background thread at app start. */
    fun preload(context: Context) {
        art(context)
    }

    private fun load(context: Context): Art {
        val text = context.assets.open("character_art.json").use { it.readBytes().decodeToString() }
        val json = JSONObject(text)
        val root = json.getJSONObject("parts")
        val params = json.getJSONArray("params").let { a -> List(a.length()) { a.getString(it) } }
        val anchors = json.getJSONArray("anchors").let { a -> List(a.length()) { a.getString(it) } }
        val shapes = HashMap<String, PathShape>()
        fun shapeOf(d: String) = shapes.getOrPut(d) { PathShape.parse(d) }
        val out = HashMap<String, List<ArtLayer>>()
        for (key in root.keys()) {
            val arr = root.getJSONArray(key)
            out[key] = List(arr.length()) { i ->
                val l = arr.getJSONArray(i)
                ArtLayer(
                    shape = shapeOf(l.getString(0)),
                    fill = Paint.parse(l.getString(1)),
                    stroke = Paint.parse(l.getString(2)),
                    width = l.getDouble(3).toFloat(),
                    alpha = l.getDouble(4).toFloat(),
                    clipShape = l.getString(5).takeIf { it.isNotEmpty() }?.let(::shapeOf),
                    morphs = if (l.length() > 6) parseMorphs(l.getJSONArray(6)) else emptyList(),
                )
            }
        }
        return Art(out, params, anchors)
    }

    private fun parseMorphs(arr: JSONArray): List<Morph> = List(arr.length()) { i ->
        val m = arr.getJSONArray(i)
        val d = m.getJSONArray(2)
        val n = d.length() / 2
        Morph(m.getInt(0), m.getInt(1) == 1, IntArray(n) { d.getInt(it * 2) }, FloatArray(n) { d.getDouble(it * 2 + 1).toFloat() })
    }
}

internal class Art(val parts: Map<String, List<ArtLayer>>, val params: List<String>, val anchorNames: List<String>)

/** Path [index] numbers move by [delta] per unit of slider [param] (of the path itself or its clip). */
internal class Morph(val param: Int, val clip: Boolean, val index: IntArray, val delta: FloatArray)

/** Absolute M / L / Q / C / Z commands and their coordinates, rebuilt into a [Path] when morphed. */
internal class PathShape(private val cmds: CharArray, val coords: FloatArray) {
    val path: Path by lazy { build(coords) }

    fun build(c: FloatArray): Path {
        val p = Path()
        var i = 0
        for (cmd in cmds) {
            when (cmd) {
                'M' -> { p.moveTo(c[i], c[i + 1]); i += 2 }
                'L' -> { p.lineTo(c[i], c[i + 1]); i += 2 }
                'Q' -> { p.quadraticTo(c[i], c[i + 1], c[i + 2], c[i + 3]); i += 4 }
                'C' -> { p.cubicTo(c[i], c[i + 1], c[i + 2], c[i + 3], c[i + 4], c[i + 5]); i += 6 }
                'Z' -> p.close()
            }
        }
        return p
    }

    companion object {
        private val ARGS = mapOf('M' to 2, 'L' to 2, 'Q' to 4, 'C' to 6, 'Z' to 0)

        fun parse(d: String): PathShape {
            val cmds = StringBuilder()
            val nums = ArrayList<Float>()
            var i = 0
            var cmd = 'M'
            var left = 0
            while (i < d.length) {
                val ch = d[i]
                when {
                    ch in ARGS -> {
                        cmd = ch
                        left = ARGS.getValue(ch)
                        cmds.append(ch)
                        i++
                    }
                    ch == '-' || ch == '.' || ch.isDigit() -> {
                        var j = i + 1
                        while (j < d.length && (d[j].isDigit() || d[j] == '.' || d[j] == 'e' || (d[j] == '-' && d[j - 1] == 'e'))) j++
                        // Implicit repeat of the last command (e.g. "L1,2 3,4").
                        if (left == 0 && cmd != 'Z') {
                            cmds.append(if (cmd == 'M') 'L' else cmd)
                            left = ARGS.getValue(cmd)
                        }
                        nums += d.substring(i, j).toFloat()
                        left--
                        i = j
                    }
                    else -> i++
                }
            }
            return PathShape(cmds.toString().toCharArray(), nums.toFloatArray())
        }
    }
}

internal class ArtLayer(
    val shape: PathShape,
    val fill: Paint?,
    val stroke: Paint?,
    val width: Float,
    val alpha: Float,
    val clipShape: PathShape?,
    val morphs: List<Morph> = emptyList(),
    pathOverride: Path? = null,
    clipOverride: Path? = null,
) {
    val path: Path = pathOverride ?: shape.path
    val clip: Path? = clipOverride ?: clipShape?.path

    /** This layer with the sliders [values] (indexed like [Art.params]) applied; itself when nothing moves. */
    fun morphed(values: FloatArray): ArtLayer {
        if (morphs.none { values.getOrElse(it.param) { 0f } != 0f }) return this
        return ArtLayer(shape, fill, stroke, width, alpha, clipShape, morphs, morph(shape, false, values)?.let(shape::build), clipShape?.let { c -> morph(c, true, values)?.let(c::build) })
    }

    /** Moved coordinates of [s], or null when no slider touches it. */
    fun morph(s: PathShape, clip: Boolean, values: FloatArray): FloatArray? {
        var out: FloatArray? = null
        for (m in morphs) {
            if (m.clip != clip) continue
            val v = values.getOrElse(m.param) { 0f }
            if (v == 0f) continue
            val c = out ?: s.coords.copyOf().also { out = it }
            for (k in m.index.indices) c[m.index[k]] += m.delta[k] * v
        }
        return out
    }
}

/** A fill / stroke: a palette role ("skin"), a fixed colour, or a gradient between two of them. */
internal sealed interface Paint {
    data class Role(val name: String) : Paint
    data class Fixed(val color: Color) : Paint
    data class Linear(val a: Paint, val b: Paint, val start: Offset, val end: Offset) : Paint
    data class Radial(val base: Paint, val alpha: Float, val center: Offset, val radius: Float) : Paint

    companion object {
        fun parse(spec: String): Paint? {
            if (spec.isEmpty()) return null
            val p = spec.split(":")
            return when (p[0]) {
                "lin" -> Linear(single(p[1]), single(p[2]), Offset(p[3].toFloat(), p[4].toFloat()), Offset(p[5].toFloat(), p[6].toFloat()))
                "rad" -> Radial(single(p[1]), p[2].toFloat(), Offset(p[3].toFloat(), p[4].toFloat()), p[5].toFloat())
                else -> single(spec)
            }
        }

        private fun single(s: String): Paint =
            if (s.startsWith("#")) Fixed(Color(s.toColorInt())) else Role(s)
    }
}
